const targetId=$input.first().json.targetId;
if(!/^[a-f0-9-]{36}$/.test(targetId||''))throw Error('Pilot deployment pending: register the approved warehouse target first');
const productRunId=$input.first().json.productRunId;
if(productRunId!=null&&!/^[A-Za-z0-9_-]{1,200}$/.test(productRunId))throw Error('Invalid product snapshot reference');
return [{json:{targetId,productRunId,runId:null||'stm-pilot-'+$execution.id}}];

const structuredClone = value => JSON.parse(JSON.stringify(value));
// Build RAW value requests only. Caller must resolve the authorized copy/tab,
// stable reservation identities, and existing row positions before using this.
// No request ever includes seating (T), label formulas (U), or attendance (AB).
const IMPORT_FIELDS = ['perks', 'guest', 'guestEmail', 'purchaser', 'purchaserEmail', 'purchaserPhone'];

// Display only: retain the original blank source name for reservation matching.
function guestDisplayName(item) {
  if (item.guest != null && typeof item.guest !== 'string') throw Error('Expected source text for guest');
  if (item.guest?.trim()) return item.guest;
  if (item.purchaser != null && typeof item.purchaser !== 'string') throw Error('Expected source text for purchaser');
  const firstName = (item.purchaser ?? '').trim().split(/\s+/u)[0];
  return firstName ? `${firstName}'s guest` : 'Guest';
}

function buildRosterRowWrites({ isPrivate, sheetName, rowLimit, rows }) {
  if (isPrivate !== false) throw new Error('Seating charts are for verified non-private classes only');
  if (typeof sheetName !== 'string' || !sheetName.trim()) throw new Error('Missing verified tab name');
  if (!Number.isSafeInteger(rowLimit) || rowLimit < 1) throw new Error('Missing verified row limit');
  if (!Array.isArray(rows)) throw new Error('Expected mapped reservation rows');
  const seenRows = new Set();
  const seenKeys = new Set();
  const tab = `'${sheetName.replace(/'/g, "''")}'`;
  const data = [];
  for (const item of rows) {
    if (!Number.isSafeInteger(item.row) || item.row < 1 || item.row > rowLimit) {
      throw new Error('Mapped row is outside the verified tab');
    }
    if (typeof item.reservationKey !== 'string' || !item.reservationKey.trim()) {
      throw new Error('Missing durable reservation identity');
    }
    if (seenRows.has(item.row) || seenKeys.has(item.reservationKey)) {
      throw new Error('Duplicate reservation identity or destination row');
    }
    seenRows.add(item.row);
    seenKeys.add(item.reservationKey);
    const cell = field => {
      if (field === 'guest') return guestDisplayName(item);
      const value = item[field];
      if (value == null) return '';
      if (typeof value !== 'string') throw new Error(`Expected source text for ${field}`);
      return value;
    };
    data.push({ range: `${tab}!V${item.row}:AA${item.row}`, values: [IMPORT_FIELDS.map(cell)] });
    data.push({ range: `${tab}!AC${item.row}`, values: [[cell('comments')]] });
  }
  return { valueInputOption: 'RAW', data };
}


// Append literal codes while retaining the exact existing text as the prefix.
function appendPerks(existing, ...additions) {
 if(typeof existing!=='string')throw Error('Perks must be literal text');
 let value=existing;
 for(const part of additions.flat()){
  if(typeof part!=='string')throw Error('Perk code must be text');
  for(const code of part.split(/[\s,;|/]+/u).filter(Boolean)){
   const escaped=code.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
   if(!new RegExp('(^|[^A-Za-z0-9])'+escaped+'($|[^A-Za-z0-9])','iu').test(value))value+=(value.trim()?', ':'')+code;
  }
 }
 return value;
}

function attachProductPerks(rows, productSource, mapping) {
 if(productSource?.complete!==true||productSource.isPrivate!==false||!Array.isArray(productSource.rows)||productSource.rows.length!==productSource.expectedRowCount)throw Error('Complete product snapshot required');
 const codes=new Set(['CAN','CP','CPM']);
 if(!Array.isArray(mapping)||mapping.length!==3||mapping.some(m=>!codes.has(m.perkCode)||!['purchaser','order','quantity'].includes(m.perkScope)))throw Error('Verified product perk mapping required');
 const result=rows.map(r=>({...r,productPerks:[]})),review=[],seen=new Set(),groups=new Map();
 for(const unit of productSource.rows){
  const id=unit.sourceOrderId+':'+unit.voucherCode;
  if(unit.classId!==productSource.classId||unit.status!=='Reserved'||!/^\d+$/.test(unit.sourceOrderId)||!unit.voucherCode||seen.has(id))throw Error('Unverified product order unit');
  seen.add(id);
  const matches=mapping.filter(m=>m.sourceNames.includes(unit.item.replace(/\s+/g,' ').trim()));
  if(matches.length!==1)throw Error('Unmapped product perks');
  const groupKey=unit.sourceOrderId+':'+matches[0].perkCode;
  const group=groups.get(groupKey)??{orderId:unit.sourceOrderId,mapping:matches[0],units:0};group.units++;groups.set(groupKey,group);
 }
 const normalize=s=>String(s??'').trim().replace(/\s+/g,' ').toLocaleLowerCase('en-US');
 for(const {orderId,mapping:m,units} of groups.values()){
  const candidates=result.filter(r=>r.sourceOrderId===orderId);
  const named=candidates.filter(r=>normalize(r.guest)&&normalize(r.guest)===normalize(r.purchaser));
  const selected=m.perkScope==='order'||m.perkScope==='quantity'&&units>=candidates.length?candidates:candidates.length===1?candidates:named.length===1?named:[];
  if(!selected.length){review.push({sourceOrderId:orderId,code:m.perkCode,reason:'product-purchaser-row-unresolved'});continue;}
  for(const row of selected)if(!row.productPerks.includes(m.perkCode))row.productPerks.push(m.perkCode);
  if(m.perkScope==='quantity'&&units>1&&units<candidates.length)review.push({sourceOrderId:orderId,code:m.perkCode,units,guestCount:candidates.length,reason:'partial-product-guest-allocation-unresolved'});
 }
 return {rows:result,review};
}

const FIELDS = ['perks', 'guest', 'guestEmail', 'purchaser', 'purchaserEmail', 'purchaserPhone', 'comments'];
const text = value => value == null ? '' : String(value);
const valuesOf = row => FIELDS.map(key => {
  if (key === 'guest') return guestDisplayName(row);
  if (row[key] != null && typeof row[key] !== 'string') throw Error('Expected literal reservation text');
  return row[key] ?? '';
});

function validateTarget(target) {
  const legacy=target?.sheetId===0&&target.sheetName==='Seating Chart Main';
  const created=/^[a-f0-9-]{36}$/.test(target?.documentGroupId??'')&&[0,1955136908].includes(target.templateSheetId)&&target.sheetId===100000000+Number(target.classId)&&typeof target.sheetName==='string'&&target.sheetName.length<=100;
  if (target?.studioCode !== 'STM' || target.isPrivate !== false || !(legacy||created)) {
    throw Error('This refresh requires a registered St Matthews class tab');
  }
  if (!target.spreadsheetId || target.spreadsheetId === target.masterSpreadsheetId || !target.masterSpreadsheetId ||
      !/^\d+$/.test(target.classId) || !Number.isSafeInteger(target.rowLimit) || target.rowLimit < 1) {
    throw Error('Missing verified pilot copy or class configuration');
  }
}

function adoptExistingRows({ target, source, cells }) {
  validateTarget(target);
  if (target.allowPilotAdoption !== true) throw Error('Existing pilot adoption is not enabled');
  // This one-time adoption is allowed only before staff have entered seats or
  // attendance, and only when every existing imported row matches fresh source.
  const available = source.rows.map(seat => ({ seat, values: valuesOf(seat) }));
  const ledger = [];
  for (let i = 0; i < cells.length; i++) {
    const c = cells[i];
    if (!Array.isArray(c) || c.length !== 10 || text(c[0]) || text(c[8])) throw Error('Pilot already has seating or attendance; review adoption');
    const values = [...c.slice(2, 8), c[9]].map(text);
    if (values.every(v => v === '')) continue;
    const match = available.findIndex(item => JSON.stringify(item.values) === JSON.stringify(values));
    if (match < 0) throw Error('Existing pilot import differs from fresh reservations');
    const item = available.splice(match, 1)[0];
    ledger.push({ reservationKey: item.seat.reservationKey, row: i + 1, lastWritten: item.values, status: 'active' });
  }
  if (available.length) throw Error('Existing pilot is not a complete source match');
  return ledger;
}

// Each destination row is read as T:AC. Only V:AA and AC can be written.
// The caller supplies a complete fresh, bounded read plus the warehouse ledger.
function planRefresh({ target, source, ledger, cells }) {
  validateTarget(target);
  if (source?.complete !== true || source.isPrivate !== false || source.studioCode !== target.studioCode ||
      source.classId !== target.classId || !Array.isArray(source.rows) || source.rows.length !== source.expectedRowCount) {
    throw Error('Incomplete or wrong studio/class source');
  }
  if (!Array.isArray(ledger) || !Array.isArray(cells) || cells.length !== target.rowLimit || cells.some(row => !Array.isArray(row) || row.length !== 10)) throw Error('Missing complete ledger or destination read');
  const rowsById = new Map();
  const occupied = new Set();
  const nextLedger = structuredClone(ledger);
  for (const entry of nextLedger) {
    if (!/^\d+$/.test(entry.reservationKey) || rowsById.has(entry.reservationKey) || occupied.has(entry.row) ||
        !Number.isSafeInteger(entry.row) || entry.row < 1 || entry.row > target.rowLimit ||
        !Array.isArray(entry.lastWritten) || entry.lastWritten.length !== FIELDS.length) throw Error('Invalid reservation row ledger');
    rowsById.set(entry.reservationKey, entry); occupied.add(entry.row);
  }
  const current = row => {
    const values = cells[row - 1];
    if (!Array.isArray(values) || values.length !== 10) throw Error('Incomplete T:AC cell read');
    return values;
  };
  const imported = row => { const c = current(row); return [...c.slice(2, 8), c[9]].map(text); };
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  const seen = new Set();
  const writes = [];
  const review = [...(source.productPerksReview??[])];
  const allocate = () => {
    // Do not reuse a removed guest's row or appropriate an existing manual row.
    for (let row = 1; row <= target.rowLimit; row++) {
      if (occupied.has(row)) continue;
      const c = current(row);
      if ([c[0], ...c.slice(2)].some(value => text(value) !== '')) continue;
      occupied.add(row); return row;
    }
    throw Error('No unused guest row remains; no rows were shifted');
  };
  for (const seat of source.rows) {
    if (!/^\d+$/.test(seat.reservationKey) || seen.has(seat.reservationKey)) throw Error('Missing or duplicate source reservation ID');
    seen.add(seat.reservationKey);
    const desired = valuesOf(seat);
    let entry = rowsById.get(seat.reservationKey);
    if (!entry) {
      entry = { reservationKey: seat.reservationKey, row: allocate(), lastWritten: Array(7).fill(''), status: 'active' };
      rowsById.set(entry.reservationKey, entry); nextLedger.push(entry);
    }
    const live = imported(entry.row);
    if ([...current(entry.row).slice(2, 8), current(entry.row)[9]].some(v => v && typeof v === 'object')) throw Error('Formula found in an owned import cell; review required');
    desired[0]=appendPerks(live[0],desired[0],seat.productPerks??[]);
    // A previous write may have succeeded before its acknowledgement was lost.
    if (!same(live.slice(1), entry.lastWritten.slice(1)) && !same(live.slice(1), desired.slice(1))) throw Error('Imported guest data was changed manually; review required');
    if (!same(live, desired)) writes.push({ ...seat, perks:desired[0],row: entry.row });
    entry.lastWritten = desired; entry.status = 'active';
  }
  for (const entry of nextLedger) {
    if (seen.has(entry.reservationKey)) continue;
    entry.status = 'removed-review';
    // Never erase or reuse a removed guest's row; keep their staff work attached.
    review.push({ reservationKey: entry.reservationKey, row: entry.row, reason: 'reservation-no-longer-active' });
  }
  const request = buildRosterRowWrites({ isPrivate: false, sheetName: target.sheetName, rowLimit: target.rowLimit, rows: writes });
  return { request, ledger: nextLedger, review, activeCount: source.rows.length, changedCount: writes.length };
}

function verifyReadback({ target, before, after, plan }) {
  validateTarget(target);
  if (before.length !== target.rowLimit || after.length !== target.rowLimit) throw Error('Incomplete verification read');
  for (let i = 0; i < target.rowLimit; i++) {
    if (before[i]?.length !== 10 || after[i]?.length !== 10) throw Error('Incomplete verification cells');
    // T seat, U label formula and AB attendance: compare user-entered values,
    // not computed formula results (which should change when names change).
    for (const column of [0, 1, 8]) if (JSON.stringify(before[i][column] ?? '') !== JSON.stringify(after[i][column] ?? '')) {
      throw Error('Protected seating, formula or attendance cell changed; do not mark success');
    }
  }
  for (const entry of plan.ledger.filter(e => e.status === 'active')) {
    const c = after[entry.row - 1];
    if (JSON.stringify([...c.slice(2, 8), c[9]].map(text)) !== JSON.stringify(entry.lastWritten)) throw Error('Reservation readback mismatch');
  }
  return { status: plan.review.length ? 'updated-needs-review' : 'updated', activeCount: plan.activeCount,
    changedCount: plan.changedCount, reviewCount: plan.review.length, seatingUnchanged: true, attendanceUnchanged: true, formulasUnchanged: true };
}

// A real store stages the complete source and immutable plan BEFORE Google.
// A durable run ID lets retries recover the same allocation after a lost reply.
function prepareRun(run, before) {
    validateTarget(run.target);
    let ledger = run.ledger;
    if (!run.plan && !ledger.length && run.target.allowPilotAdoption) ledger = adoptExistingRows({ target: run.target, source: run.source, cells: before });
    const plan = run.plan ?? planRefresh({ target: run.target, source: run.source, ledger, cells: before });
    if (run.plan) {
      // A staged plan can be retried after a partial/lost Google response, but
      // cannot overwrite a third value entered by staff since it was staged.
      for (const entry of plan.ledger.filter(e => e.status === 'active')) {
        const old = run.ledger.find(e => e.reservationKey === entry.reservationKey)?.lastWritten ?? Array(7).fill('');
        const live = before[entry.row - 1];
        const imported = [...live.slice(2, 8), live[9]];
        if (imported.some((v, i) => v && typeof v === 'object' || text(v) !== old[i] && text(v) !== entry.lastWritten[i])) {
          throw Error('Pending refresh conflicts with a staff edit; review required');
        }
      }
    }
    return plan;
}

async function refreshReservations({ targetId, runId, source, store, sheets }) {
  const run = await store.claim({ targetId, runId, source });
  if (run.completed) return run.result;
  try {
    const before = await sheets.read(run.target);
    const plan = prepareRun(run, before);
    if (!run.plan) await store.stage({ runId, plan });
    if (plan.request.data.length) await sheets.write(run.target, plan.request);
    const after = await sheets.read(run.target);
    const result = verifyReadback({ target: run.target, before, after, plan });
    await store.complete({ runId, plan, result });
    return result;
  } catch (error) {
    await store.fail({ runId, reason: 'refresh-failed-review-required' });
    throw error;
  }
}



const items=$input.all().map(i=>i.json); if(items.length!==1)throw Error('Exactly one pilot target required');
const record=items[0], target=record.config; validateTarget(target);
if(!record.enabled||record.studio_id!==target.studioId||target.googleAccountEmail!=="pinotsstmatthews@gmail.com"||target.masterSpreadsheetId!=="1ktf-zV74f--JWaaPlrrtYgmbLVGI6ZJI9JdArrYootA"||!Number.isSafeInteger(target.accountId))throw Error('Warehouse source/account configuration mismatch');
return [{json:target}];

// Normalize the verified class seating table for ETL; no collection or writes.
const HEADERS = ['Order Id', 'Perks', 'Guest', 'Guest Email', 'Purchaser',
  'Purchaser Email', 'Purchaser Phone', 'Checked In', 'Comments'];
const normalizeHeader = value => String(value).trim().replace(/\s+/g, ' ').toLowerCase();

function normalizeSeatingTable({ isPrivate, complete, expectedRowCount, headers, rows }) {
  if (isPrivate !== false) throw new Error('Only classes have seating rosters');
  if (complete !== true) throw new Error('Incomplete source seating table');
  if (!Array.isArray(headers) || headers.length !== HEADERS.length ||
      headers.some((value, i) => normalizeHeader(value) !== normalizeHeader(HEADERS[i]))) {
    throw new Error('Source seating columns changed; review before importing');
  }
  if (!Array.isArray(rows) || !Number.isSafeInteger(expectedRowCount) ||
      expectedRowCount < 0 || rows.length !== expectedRowCount) {
    throw new Error('Seating row count is unverified or incomplete');
  }
  return rows.map((row, sourceRowIndex) => {
    if (!Array.isArray(row) || row.length !== HEADERS.length) {
      throw new Error('Source seating row has the wrong column count');
    }
    const cells = row.map((value, column) => {
      if (value == null) return '';
      if (typeof value === 'string') return value;
      if (column === 0 && Number.isSafeInteger(value)) return String(value);
      throw new Error('Expected source seating text');
    });
    if (!/^\d+$/.test(cells[0])) throw new Error('Missing source order ID');
    return {
      // Order ID and source row index are context, not durable guest identity.
      sourceOrderId: cells[0], sourceRowIndex,
      perks: cells[1], guest: cells[2], guestEmail: cells[3],
      purchaser: cells[4], purchaserEmail: cells[5], purchaserPhone: cells[6],
      // Checked In at index 7 is intentionally excluded; Comments keeps AC.
      comments: cells[8],
    };
  });
}


// The order grid's reservationCheckbox value is the real per-seat ID. Kendo's
// data-uid, display order, purchaser name and order ID are not guest identities.
function identifyReservations(source) {
  const seats = normalizeSeatingTable(source);
  if (!Array.isArray(source.reservations)) throw Error('Missing reservation identities');
  const groups = new Map();
  const ids = new Set();
  // Seating's Comments can include Pinot-generated text not present in the
  // order's Seating Requests control (observed on the real pilot). Match on
  // order/name/email; require all imported fields identical within duplicates.
  const signature = r => JSON.stringify([r.sourceOrderId, r.guest, r.guestEmail]);
  for (const r of source.reservations) {
    if (!/^\d+$/.test(r.reservationId) || !/^\d+$/.test(r.sourceOrderId) || ids.has(r.reservationId)) {
      throw Error('Missing or duplicate reservation ID');
    }
    ids.add(r.reservationId);
    if (!['Active', 'On Hold', 'Refunded'].includes(r.status)) throw Error('Unknown reservation status');
    if (r.status !== 'Active') continue;
    for (const key of ['guest', 'guestEmail', 'comments']) if (typeof r[key] !== 'string') throw Error('Incomplete reservation detail');
    const key = signature(r);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }
  const byIndex = new Map();
  const payload = s => JSON.stringify([s.perks, s.guest, s.guestEmail, s.purchaser, s.purchaserEmail, s.purchaserPhone, s.comments]);
  // Admin sometimes repeats the purchaser's name/email on every seating row,
  // while the actual order retains an unnamed guest. Reconcile only when all
  // seating fields are identical, counts agree, and the order contains that
  // purchaser plus genuinely blank guests. The order's real IDs/names remain
  // authoritative; differing perks or other named guests still stop matching.
  for (const orderId of new Set(seats.map(s => s.sourceOrderId))) {
    const values = seats.filter(s => s.sourceOrderId === orderId);
    const reservations = [...groups.values()].flat().filter(r => r.sourceOrderId === orderId);
    const sample = values[0];
    const named = reservations.filter(r => signature(r) === signature(sample));
    const blank = reservations.filter(r => r.guest === '' && r.guestEmail === '');
    if (values.length < 2 || reservations.length !== values.length || !sample.guest ||
        sample.guest !== sample.purchaser || sample.guestEmail !== sample.purchaserEmail ||
        new Set(values.map(payload)).size !== 1 || !named.length || !blank.length ||
        named.length + blank.length !== reservations.length) continue;
    reservations.sort((a,b) => a.reservationId.localeCompare(b.reservationId,'en',{numeric:true}));
    values.forEach((seat,i) => byIndex.set(seat.sourceRowIndex, {...seat,
      guest:reservations[i].guest,guestEmail:reservations[i].guestEmail,reservationKey:reservations[i].reservationId}));
    for (const [key,rows] of groups) if (rows[0].sourceOrderId === orderId) groups.delete(key);
  }
  const seatGroups = new Map();
  for (const seat of seats) {
    if (byIndex.has(seat.sourceRowIndex)) continue;
    const key = signature(seat);
    if (!seatGroups.has(key)) seatGroups.set(key, []);
    seatGroups.get(key).push(seat);
  }
  if (groups.size !== seatGroups.size) throw Error('Order and seating sources disagree');
  for (const [key, values] of seatGroups) {
    const reservations = groups.get(key);
    if (!reservations || reservations.length !== values.length) throw Error('Order and seating seat counts disagree');
    // Indistinguishable guests are safe only if EVERY imported field is equal.
    // Different perks/details on duplicate names cannot be guessed onto IDs.
    if (new Set(values.map(payload)).size !== 1) throw Error('Ambiguous duplicate guest details');
    reservations.sort((a, b) => a.reservationId.localeCompare(b.reservationId, 'en', { numeric: true }));
    values.forEach((seat, i) => byIndex.set(seat.sourceRowIndex, { ...seat, reservationKey: reservations[i].reservationId }));
  }
  return seats.map(seat => byIndex.get(seat.sourceRowIndex));
}


const payload=$input.first().json,target=$('Validate STM pilot target').first().json;
if(payload.success!==true||payload.accountId!==target.accountId||payload.studioId!==target.studioId||payload.source?.classId!==target.classId||payload.source?.studioCode!==target.studioCode)throw Error('Wrong or incomplete source account/class');
const raw=payload.source;
function scheduledSourceGuard(details,scheduledStartAt,now=new Date().toISOString()){
 if(!scheduledStartAt)return;
 const start=Date.parse(scheduledStartAt),at=Date.parse(now);
 if(!Number.isFinite(start)||!Number.isFinite(at)||at>start-70*60000||details?.isPublished!==true)throw Error('Scheduled class is unpublished, late or unverified');
 const m=/^(?:[A-Za-z]{3}, )?(\d{1,2}) ([A-Za-z]{3}) (\d{4})$/.exec(details.dateText??'');
 const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 const actual=m&&months.includes(m[2])?`${m[3]}-${String(months.indexOf(m[2])+1).padStart(2,'0')}-${m[1].padStart(2,'0')}`:null;
 const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date(start));
 const clock=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}).format(new Date(start));
 if(actual!==day||details.startTimeText?.replace(/\s+/g,' ').trim()!==clock)throw Error('Class time changed; review the workbook before scheduled updates');
}
